def balanced(s):
    # State machine approach
    in_string = None  # None, "'", or '"'
    escape_next = False
    stack = []

    for ch in s:
        if escape_next:
            # The escaped character is ignored for nesting purposes
            escape_next = False
            continue

        if in_string is not None:
            # Inside a quoted string
            if ch == '\\':
                escape_next = True
            elif ch == in_string:
                in_string = None
            # All other characters inside string are ignored
        else:
            # Outside quoted strings
            if ch in ('"', "'"):
                in_string = ch
            elif ch in '([{':
                stack.append(ch)
            elif ch in ')]}':
                if not stack:
                    return False
                top = stack.pop()
                # Check matching
                if (top == '(' and ch != ')') or \
                   (top == '[' and ch != ']') or \
                   (top == '{' and ch != '}'):
                    return False
            # backslash outside string is ordinary character, ignore

    # If string is still open at end, return False
    if in_string is not None:
        return False

    # Stack must be empty
    return len(stack) == 0


